import {GAMES,CHAPTERS,DEFAULT_PACK} from './server/content.mjs';
import {MAP,distance,walkable} from './server/map.mjs';
import {findPath} from './server/navigation.mjs';
import {drawKruger,worldPoint,portrait} from './kruger-client.mjs';
let krugerApproach=null,rpgTapQueue=0,rpgTapSending=false,rpgTapAt=0;
let krugerSelection=null,krugerPath=[],krugerCamera=null,krugerZoom=1,krugerOverview=false,krugerChapter='',krugerAuto=false,krugerAutoAt=0,moveSending=false;
const app=document.querySelector('#app');
const API=window.LANPARTY_API||'/api/room';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(s)=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const params=new URLSearchParams(location.search);const requested=params.get('room')?.toUpperCase();
let sequencePattern=[],sequenceQueue=[],sequenceSending=false,sequenceLocalCursor=0,sequenceLastWrong=0;
let previewMode=false,previewState=null,previewEngine=null,previewScreen='player',previewBotAt=0,previewStarted=0,restoreTool='clean',restoreQueue=[],restoreSending=false,restorePointer=false,restoreHover=null;
let session=null,room=null,key='',busy=false,polling=false,failures=0,clockOffset=0,animation=0,mapPosition=null,moveSeq=0,moveLast=0,direction={x:0,y:0},drawing=[],stroke=null,drawingSent=false,lastGestureTask=-1,holdStart=0,trace=[],swipeX=0;
try{const stored=JSON.parse(sessionStorage.getItem('sumthing-session'));if(stored&&(!requested||stored.role==='player'&&stored.code===requested))session=stored;}catch{}
if(params.has('preview'))session=null;
const now=()=>Date.now()+clockOffset;
function toast(text){const t=$('#toast');t.textContent=text;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200);}
function save(){sessionStorage.setItem('sumthing-session',JSON.stringify(session));}
function joinURL(code){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('room',code);return url.href;}
async function request(op,data={}){if(previewMode)return previewRequest(op,data);const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);try{const res=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...session,op,...data}),signal:controller.signal});const value=await res.json();if(!res.ok)throw Error(value.error||'Could not reach the room.');return value;}finally{clearTimeout(timeout);}}
function accept(value){if(room&&room.code===value.code&&value.revision<room.revision)return;room=value;clockOffset=value.serverNow-Date.now();failures=0;render();}
async function action(op,data={}){if(busy)return;busy=true;try{accept(await request(op,data));}catch(e){toast(e.name==='AbortError'?'Connection timed out. Try again.':e.message);}finally{busy=false;}}
async function host(actionData){if(previewMode&&actionData.type==='menu'){stopPreview();return;}return action('host',{action:actionData});}
async function play(actionData){return action('player',{action:actionData});}
async function poll(){if(previewMode){try{accept(previewRequest('state'));}catch(e){toast(e.message);}return;}if(!session||polling)return;polling=true;try{accept(await request('state'));}catch(e){failures++;if(failures===2)toast('Connection interrupted. Reconnecting…');if(failures>4&&/expired|not found|session/.test(e.message)){toast(e.message);session=null;room=null;sessionStorage.removeItem('sumthing-session');key='';render();}}finally{polling=false;}}
function header(){return `<header class="site-header"><a class="wordmark" href="./"><img src="./assets/sumthing-logo.svg" alt="Sumthing" width="60" height="52"><span class="sub">LAN PARTY<br>FIVE YEAR EDITION</span></a><div class="header-right"><a class="preview-nav" href="?preview=all" data-preview-menu>Try all games</a><span class="tag pill">3—10 PLAYERS</span></div></header>`;}
function footer(){return `<footer class="footer"><span>SUMTHING LAN PARTY © 2026</span><span>FIVE YEARS. FIVE GAMES. YOUR PEOPLE.</span><span>PHONE IN HAND. TEAM ON SCREEN.</span></footer>`;}
function preview(type){if(type==='quiz')return `<span class="giant">?!</span>`;if(type==='bluff')return `<div class="pixel-row"><i class="pixel-person" style="--shirt:#d0b2f3"></i><i class="pixel-person" style="--shirt:#ffbd7e"></i><i class="pixel-person" style="--shirt:#8cdbc0"></i><span class="giant" style="font-size:70px">?</span></div>`;if(type==='kruger')return `<canvas class="map-preview" width="600" height="260" style="width:100%;height:100%;object-fit:cover;image-rendering:pixelated"></canvas>`;if(type==='restore')return `<div class="pixel-row"><span class="tree">♠</span><span class="tree" style="font-size:105px">♠</span><span class="tree">♠</span></div><span class="ground"></span>`;return `<svg width="180" height="130" viewBox="0 0 180 130" aria-hidden="true"><path d="M22 103L35 52 80 45 115 62 140 37 156 96 107 106 67 98Z M35 52L62 21 80 45M54 69L92 72M65 98L62 78M105 78L107 106" stroke="currentColor" stroke-width="5" fill="none"/><circle cx="60" cy="61" r="3" fill="currentColor"/></svg>`;}
function cabinets(hostMode=false){return `<div class="game-grid">${Object.entries(GAMES).map(([id,g],i)=>`<article class="cabinet" style="--accent:${g.color}"><div class="marquee"><strong>0${i+1} / ${g.short}</strong><span class="mono" style="font-size:9px">${g.minutes}</span></div><div class="preview">${preview(id)}</div><div class="cabinet-body"><h3>${esc(g.title)}</h3><p>${esc(g.description)}</p><div class="cabinet-foot"><span class="mono" style="font-size:8px">${g.genre}</span><button class="btn ${hostMode?'small':'lime'}" ${hostMode?`data-start="${id}"`:`data-preview="${id}"`}>${hostMode?'START GAME ↗':'PLAY PREVIEW ↗'}</button>${!hostMode?`<button class="how-link" data-help="${id}">How to play</button>`:''}</div></div></article>`).join('')}</div>`;}
function home(){return `${header()}<main class="wrap"><section class="hero"><div><p class="eyebrow">FIVE YEARS OF RESTORING NATURE</p><h1>FIVE YEARS.<br>LET’S <span>PLAY.</span></h1><p>Company legends. Neighbourhood chaos. Nature to restore.<br>Five games made for the people behind Sumthing.</p><div class="hero-actions"><a class="btn lime" href="#games" data-preview-menu>TRY THE GAMES <span>↗</span></a><button class="btn primary" data-create="false">HOST A PARTY <span>↗</span></button><button class="btn" data-join>JOIN ON YOUR PHONE <span>→</span></button></div><p class="form-note">Put the host screen on the TV. Everyone else brings a phone.<br><button class="text-button" data-create="true" style="border:0;background:none;text-decoration:underline;padding:0;font-size:11px">Create a one-player practice room</button></p></div><div class="hero-art" aria-hidden="true"><span class="birthday">5</span></div></section><div class="arcade-top" id="games"><h2>FIVE GAMES TO TRY</h2><span class="mono">INSTANT SOLO PREVIEWS<br>NO ROOM OR PHONE NEEDED</span></div>${cabinets()}${footer()}</main>`;}
function joinPage(){return `${header()}<main class="wrap"><section class="join-section"><p class="eyebrow">YOUR PHONE IS YOUR CONTROLLER</p><h1>PLAYER,<br>YOU’RE UP.</h1><form id="join-form"><div class="field"><label for="room-code">ROOM CODE</label><input id="room-code" name="code" value="${esc(requested||'')}" placeholder="ABC123" maxlength="6" minlength="6" pattern="[a-zA-Z0-9]{6}" required autocapitalize="characters" autocomplete="off"></div><div class="field"><label for="player-name">YOUR PLAYER NAME</label><input id="player-name" name="name" maxlength="24" placeholder="What should we call you?" autocomplete="nickname" required></div><button class="btn primary" type="submit">LET ME IN →</button></form><p class="form-note">Use the code on the big screen. No account needed.<br>Rooms expire after six hours. Scores belong to each game.</p><button class="btn small" data-back>BACK TO THE ARCADE</button></section></main>`;}
function roster(){return `<div class="roster">${room.players.map(p=>`<span class="player-chip ${p.online?'':'offline'}"><i class="color" style="background:${p.color}"></i>${esc(p.name)}${room.host?`<button class="kick" aria-label="Remove ${esc(p.name)}" data-kick="${p.id}">×</button>`:''}</span>`).join('')||'<span class="muted">Waiting for your first player…</span>'}</div>`;}
function roomHeader(){if(previewMode)return previewHeader();return `${header()}<section class="room-head"><div><p class="eyebrow">${room.host?'JOIN THIS PARTY':'YOU’RE IN'}${room.practice?' · PRACTICE ROOM':''}</p><p class="room-code">${room.code}</p><a href="${esc(joinURL(room.code))}" target="_blank" rel="noopener">${esc(new URL(joinURL(room.code)).host+new URL(joinURL(room.code)).pathname)}?room=${room.code}</a></div>${room.host?'<div class="qr" id="qr" aria-label="Scan to join this room"></div>':''}<div class="actions"><button class="btn small" data-copy> COPY JOIN LINK</button>${room.host?'<button class="btn small" data-fullscreen>FULL SCREEN</button>':''}<button class="btn small" data-leave>LEAVE</button><span class="connection" id="connection">CONNECTED</span></div></section>`;}
function tools(){return `<details class="content-tools"><summary>YOUR COMPANY CONTENT · ${room.sample?'SAMPLE PACK LOADED':'CUSTOM PACK LOADED'}</summary><p>Import a content pack before a game. It replaces the quiz, characters and drawing prompts in this room. Other rooms are unaffected.</p><div class="actions"><button class="btn small" data-download>DOWNLOAD SAMPLE JSON</button><label class="btn small" style="cursor:pointer;letter-spacing:0;font-family:inherit;text-transform:none">IMPORT JSON FILE<input type="file" id="pack-file" accept="application/json,.json" hidden></label></div><div class="field"><label for="pack-json">OR PASTE YOUR JSON CONTENT PACK</label><textarea id="pack-json" spellcheck="false" placeholder="Paste the edited content pack here"></textarea></div><button class="btn primary small" data-save-pack>USE THIS CONTENT PACK</button><p class="host-pack-message" id="pack-message"></p></details>`;}
function lobby(){if(room.host)return `${roomHeader()}<main class="wrap room-content"><div class="room-intro"><div><p class="eyebrow">THE PARTY LOBBY</p><h2>YOUR PEOPLE. YOUR ARCADE.</h2><p class="muted">${room.players.length}/10 players joined. ${room.practice?'Practice mode allows one player.':'Three players needed to start.'} Pick a game when everyone is ready.</p></div><span class="tag">EACH GAME STARTS AT ZERO</span></div>${roster()}${room.sample?'<div class="sample-banner">Sample content is loaded. Replace the fictional character stories and drawing prompts with your own company legends before the event.</div>':''}${room.history.length?`<div class="history">${room.history.map(h=>`<span>${esc(GAMES[h.type].short)} · ${esc(h.winners.join(' + '))}</span>`).join('')}</div>`:''}${tools()}${cabinets(true)}${footer()}</main>`;
return `${roomHeader()}<main class="phone-shell"><div class="waiting"><i class="pixel-person" style="--shirt:${me().color}"></i><p class="eyebrow">HEY ${esc(me().name)}</p><h2>READY WHEN<br>YOU ARE.</h2><p class="muted">The host is choosing a game.<br>Keep this page open. Your controls appear here.</p></div>${roster()}</main>`;}
function me(){return room.players.find(p=>p.id===room.me);}
function scores(){return `<aside class="scoreboard"><h3>THIS GAME’S SCORES</h3>${[...room.players].sort((a,b)=>b.score-a.score).map((p,i)=>`<div class="score-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><i class="color" style="background:${p.color}"></i><span>${esc(p.name)}</span><strong data-score="${p.id}">${p.score}</strong></div>`).join('')}</aside>`;}
function timer(){return '<span class="countdown" data-timer></span>';}
function hostControls(){if(room.game.type==='kruger'&&room.game.phase!=='results')return `<div class="host-controls">${room.game.conversation?'<button class="btn primary" data-rpg-host>CONTINUE SCENE →</button>':''}<button class="btn" data-advance>${room.game.phase==='chapter-end'?'NEXT CHAPTER →':'SKIP TO CHAPTER END'}</button><button class="btn" data-finish>FINISH GAME</button><button class="btn" data-menu>RETURN TO ARCADE</button></div>`;return `<div class="host-controls">${room.game.phase!=='results'?'<button class="btn primary" data-advance>CONTINUE / REVEAL →</button><button class="btn" data-finish>FINISH THIS GAME</button>':''}<button class="btn" data-menu>RETURN TO ARCADE</button></div>`;}
function frame(content,{wide=false}={}){const g=room.game;return `${roomHeader()}<main class="${room.host?'wrap room-content':'phone-shell'}">${room.host?`<div class="stage-header"><div><p class="eyebrow">${GAMES[g.type].genre} · ${room.sample?'SAMPLE EDITION':'COMPANY EDITION'}</p><h2>${esc(GAMES[g.type].title)}</h2></div>${timer()}</div><div class="stage-grid"><div>${content}${hostControls()}</div>${scores()}</div>`:`<div class="phone-title"><span>${esc(me().name)} · <b data-score="${me().id}">${me().score}</b> PTS</span>${timer()}</div>${content}`}</main>`;}
function quiz(){const g=room.game;return frame(`<section class="stage"><p class="eyebrow">QUESTION ${g.index+1} / ${g.total}</p><h2>${esc(g.question)}</h2><div class="answer-grid">${g.answers.map((a,i)=>`<button class="answer-btn ${g.phase==='reveal'&&i===g.correct?'correct':''} ${g.myAnswer===i?'selected':''}" ${room.host||g.phase!=='answer'||g.myAnswer!==undefined?'disabled':''} data-answer="${i}"><b>${'ABCD'[i]}</b>${esc(a)}</button>`).join('')}</div>${g.phase==='reveal'?`<p class="notice">${esc(g.story)}</p>`:`<p class="submitted"><span data-submitted>${g.answered.length}</span> / ${room.players.length} ANSWERS LOCKED ${g.myAnswer!==undefined?'· YOUR ANSWER IS IN':''}</p>`}</section>`);}
function bluff(){const g=room.game,c=g.character;return frame(`<section class="stage"><p class="eyebrow">LEGEND ${g.index+1} / ${g.total} · ${esc(g.phase)}</p><div class="pixel-row" aria-hidden="true"><i class="pixel-person" style="--shirt:#c8a9ed"></i></div><h2>${esc(c.name)}</h2><p class="muted">${esc(c.description)}</p><h3>${esc(c.prompt)}</h3>${g.phase==='write'?(room.host?`<p class="notice">Players are inventing believable endings. The real answer stays hidden until the reveal.</p><p class="submitted"><span data-submitted>${g.submitted.length}</span> / ${room.players.length} BLUFFS SUBMITTED</p>`:g.myBluff?`<p class="notice">Your bluff is in: “${esc(g.myBluff)}”</p><p class="submitted">WAIT FOR THE VOTE</p>`:`<form id="bluff-form"><div class="field"><label for="bluff-text">YOUR CONVINCING FAKE ENDING</label><textarea id="bluff-text" maxlength="140" required placeholder="Make it sound almost true…"></textarea></div><button class="btn lime" type="submit">SUBMIT MY BLUFF →</button></form>`):`<div class="answer-grid">${(g.options||[]).map((o,i)=>`<button class="answer-btn ${o.truth?'correct':''} ${g.myVote===o.id?'selected':''}" ${room.host||g.phase!=='vote'||g.myVote||o.mine?'disabled':''} data-vote="${o.id}"><b>${i+1}</b>${esc(o.text)}${o.mine?' (your bluff)':''}${o.truth?' · THE TRUTH':''}</button>`).join('')}</div>${g.phase==='vote'?`<p class="submitted"><span data-submitted>${g.voted.length}</span> / ${room.players.length} VOTES LOCKED</p>`:`<p class="notice">${esc(g.story)}</p>`}`}</section>`);}
function sketch(){const g=room.game;const artist=room.players.find(p=>p.id===g.artist);const mine=g.artist===room.me;
if(g.phase==='draw')return frame(`<section class="stage"><p class="eyebrow">60 SECONDS · DRAW THE MEMORY</p><h2>${room.host?'PENS AT THE READY.':esc(g.myPrompt)}</h2>${room.host?`<p class="notice">Everyone gets a different prompt. Their drawings will appear here one by one.</p><p class="submitted"><span data-submitted>${g.submitted.length}</span> / ${room.players.length} DRAWINGS SUBMITTED</p>`:`<canvas id="draw" width="640" height="480" class="draw-canvas" aria-label="Draw your prompt with a finger or mouse"></canvas><div class="drawing-actions"><button class="btn small" data-clear-drawing>CLEAR</button><button class="btn lime small" data-send-drawing>SAVE DRAWING</button></div><p class="submitted" id="drawing-status">DRAW WITH YOUR FINGER. SAVE WHEN READY.</p>`}</section>`);
return frame(`<section class="stage"><p class="eyebrow">DRAWING ${g.artist?room.players.indexOf(artist)+1:1} / ${room.players.length} · ${esc(artist?.name)}</p><h2>${g.phase==='reveal'?esc(g.prompt):'WHAT’S THE STORY?'}</h2><div class="drawing-view"><canvas id="drawing-view" class="draw-canvas" width="640" height="480" aria-label="The current player's drawing"></canvas></div>${!room.host&&g.phase==='guess'&&!mine?`<form id="guess-form"><div class="field"><label for="guess-text">GUESS THE DRAWING</label><input id="guess-text" maxlength="120" required autocomplete="off" placeholder="What do you think it is?"></div><button class="btn lime" type="submit">GUESS →</button></form><p class="submitted" id="guess-status">${g.correctGuessers.includes(room.me)?'CORRECT! YOU FOUND IT.':g.myGuess?'LAST GUESS: '+esc(g.myGuess):'YOU CAN MAKE UP TO EIGHT GUESSES.'}</p>`:mine&&g.phase==='guess'?'<p class="notice">This is your masterpiece. Let the others guess!</p>':''}${room.host&&g.phase==='reveal'?`<p class="notice">Exact answers score automatically. Accept a close answer below if a player described the right thing.</p><div class="actions">${room.players.filter(p=>p.id!==artist.id).map(p=>`<button class="btn lime small" ${g.correctGuessers.includes(p.id)?'disabled':''} data-award="${p.id}">${esc(p.name)}: ${esc(g.guesses?.[p.id]||'—')} +100</button>`).join('')}</div>`:''}</section>`);}
function restore(){const g=room.game;const actions=[['✳','Seed','#c7f50a'],['◒','Water','#87d1e2'],['☀','Sun','#ffd46c'],['♠','Leaf','#76c998']];return frame(`<section id="habitat-game" class="habitat-game"><div class="habitat-game-top"><span>PATTERN ${g.sequenceRound+1}</span><span><b data-progress>${g.progress}</b> HABITATS RESTORED</span><b id="sequence-remaining"></b></div>${room.host||previewMode?`<div class="sequence-tv"><p class="small-label">${previewMode?'TV PREVIEW · WATCH HERE':'WATCH THE BIG SCREEN'}</p><h3 id="sequence-message">WATCH THE ORDER</h3><div class="sequence-cues">${actions.map(([icon,label,color],i)=>`<div data-sequence-cue="${i}" style="--cue:${color}"><span>${icon}</span><small>${label}</small></div>`).join('')}</div></div>`:'<div class="sequence-phone-watch"><h3 id="sequence-message">WATCH THE TV</h3><p>Remember the order. Tap it here when GO appears.</p></div>'}${room.host?`<div class="habitat-garden"><div id="habitat-trees"></div><div class="habitat-players">${room.players.map((p,i)=>`<div class="habitat-player" data-sequence-player="${p.id}">${animalAvatar(i,p.color)}<b>${esc(p.name)}</b><span class="habitat-player-status">WATCHING</span><small class="habitat-player-count">${p.restored||0} habitats</small></div>`).join('')}</div></div>`:`<div class="sequence-personal-line"><strong id="sequence-personal"></strong><span id="sequence-tries"></span></div><div id="sequence-dots" class="sequence-dots"></div><div class="sequence-phone-buttons">${actions.map(([icon,label,color],i)=>`<button data-sequence-button="${i}" style="--cue:${color}" ${g.sequencePhase!=='repeat'?'disabled':''}><span>${icon}</span><b>${label}</b><small>${i+1}</small></button>`).join('')}</div><p class="form-note">Copy the order from the TV. Finish a pattern to restore a habitat. Wrong taps reset your attempt; three mistakes sit out this pattern.</p>`}</section>`);}
function rpgDialogue(){const c=room.game.conversation;if(!c)return '';const phone=!room.host;return `<section class="rpg-dialogue" aria-label="Shared neighbourhood conversation"><div class="rpg-speaker">${portrait(c.look)}<div><strong>${esc(c.name)}</strong><small>${esc(c.role)}</small></div><span class="rpg-scene-badge">${c.stage==='vote'?'GROUP CHOICE':c.stage==='challenge'?'TEAM EFFORT':'EVERYONE IS IN THIS SCENE'}</span></div><p class="rpg-dialogue-text">${esc(c.text)}</p>${c.stage==='vote'?`<div class="rpg-choices">${c.options.map((option,i)=>`<button data-rpg-vote="${i}" ${!phone?'disabled':''}><b>${'ABC'[i]}</b><span>${esc(option)}</span><i data-vote-mark="${i}"></i></button>`).join('')}</div><p class="rpg-dialogue-status" id="rpg-ready-status"></p>`:c.stage==='challenge'?`<div class="rpg-effort"><div><i id="rpg-effort-fill"></i></div><p id="rpg-effort-label"></p>${phone?`<button class="rpg-a-button mash" data-rpg-tap><b>A</b><span>${esc(c.verb)}</span></button>`:'<p class="rpg-tv-instruction">EVERYONE TAP A ON YOUR PHONE!</p>'}<small id="rpg-personal-taps"></small></div>`:c.stage==='done'?`<div class="rpg-new-item"><span>★ NEW SOUVENIR</span><strong>${esc(c.item)}</strong></div>${phone?'<button class="rpg-a-button" data-rpg-ready><b>A</b><span>BACK TO THE SQUARE</span></button>':''}<p class="rpg-dialogue-status" id="rpg-ready-status"></p>`:`${c.stage==='outcome'?`<div class="rpg-vote-result">THE SQUARE CHOSE ${'ABC'[c.choice]} · ${c.counts.join(' / ')} VOTES${c.tied?' · TIE BROKEN BY THE CONVERSATION STARTER’S VOTE, THEN A–C':''}</div>`:''}${phone?'<button class="rpg-a-button" data-rpg-ready><b>A</b><span>CONTINUE TOGETHER ▾</span></button>':'<p class="rpg-tv-instruction">READ IT OUT LOUD · PLAYERS PRESS A TO CONTINUE</p>'}<p class="rpg-dialogue-status" id="rpg-ready-status"></p>`}</section>`;}
function kruger(){const g=room.game;if(g.phase==='chapter-end')return frame(`<section class="rpg-chapter-end"><p class="eyebrow">CHAPTER COMPLETE · ${g.chapter+1} / 4</p><h2>${esc(g.chapterInfo.title)}</h2><p>You met ${g.chapterDone} neighbours and collected ${g.souvenirs.length} very questionable souvenirs.</p><div class="rpg-souvenirs">${g.souvenirs.filter(i=>i.chapter===g.chapter).map(i=>`<span>★ ${esc(i.name)}</span>`).join('')}</div><p>${g.chapter===3?'Next stop: Hortus. Same people. Better stories.':'The host can open the next chapter when everyone is ready.'}</p></section>`);
return frame(`<section class="rpg-machine ${g.conversation?'in-conversation':''}"><div class="rpg-topline"><span>KRUGERPLEIN / ${String(g.chapter+1).padStart(2,'0')}</span><span>${g.chapterDone}/${g.chapterTotal} STORIES · ★ ${g.streetCred} STREET CRED</span></div><div class="rpg-location"><strong>${esc(g.chapterInfo.title)}</strong><span>${g.conversation?'A wild conversation appeared.':esc(g.chapterInfo.subtitle)}</span></div><div class="rpg-world"><canvas id="kruger-canvas" tabindex="0" aria-label="Pixel map of Krugerplein. Tap a neighbour with an exclamation mark to walk over and talk."></canvas>${!g.conversation?'<div class="rpg-map-actions"><button data-overview>MAP</button><button data-stop-walk>STOP</button></div>':''}</div>${g.conversation?rpgDialogue():`<div class="rpg-explore">${!room.host?'<div class="rpg-dpad"><button data-dir="up" aria-label="Walk north">↑</button><button data-dir="left" aria-label="Walk west">←</button><button data-dir="right" aria-label="Walk east">→</button><button data-dir="down" aria-label="Walk south">↓</button></div>':''}<div><span class="rpg-small">YOUR NEXT ENCOUNTER</span><strong id="rpg-target-name"></strong><small id="rpg-target-role"></small></div>${!room.host?'<button class="rpg-a-button" data-route><b>A</b><span>TALK</span></button>':'<p class="rpg-tv-instruction">EXPLORE ON YOUR PHONES</p>'}</div><div class="rpg-neighbours" id="rpg-neighbours"></div><p class="rpg-help">${room.host?'One player starts a chat. Everyone joins the conversation and chooses the reply.':'Tap a neighbour below or explore the map. One person starts a chat; the whole group decides what to say.'}</p>`}<details class="rpg-bag"><summary>▣ BAG · ${g.souvenirs.length} SOUVENIRS</summary><div>${g.souvenirs.map(i=>`<p>★ ${esc(i.name)}<small>From ${esc(i.from)}</small></p>`).join('')||'<p>Your bag is empty. Your company’s potential is not.</p>'}</div></details></section><p class="rpg-fiction">Original arcade dialogue inspired by your brief. Invented lines, awaiting your real anecdotes. Map based on PDOK aerial imagery; office interior is stylised.</p>`);}
function results(){const g=room.game;return `${roomHeader()}<main class="wrap room-content"><section class="result-stage"><p class="eyebrow">${esc(GAMES[g.type].title)} · GAME COMPLETE</p><h1>${g.winners.length>1?'SHARED GLORY.':'TAKE A BOW.'}</h1><p class="winner">${esc(g.winners.join(' + '))}</p><p>Winner${g.winners.length>1?'s':''} of this minigame. A fresh game starts with fresh scores.</p>${scores()}${room.host?'<button class="btn" data-menu>BACK TO THE ARCADE →</button>':'<p class="eyebrow">THE HOST WILL CHOOSE WHAT’S NEXT</p>'}</section></main>`;}
function render(){const g=room?.game;document.body.classList.toggle('in-game',!!g);document.body.classList.toggle('host-mode',!!room?.host);document.body.classList.toggle('rpg-mode',g?.type==='kruger');const renderKey=!room?(session?'loading':window.joinMode||requested?'join':'home'):[room.code,room.host,room.players.map(p=>p.id).join(),room.sample,g?.type,g?.phase,g?.index,g?.chapter,g?.conversation?.id,g?.conversation?.stage,g?.conversation?.page,g?.completed?.length,g?.artist,g?.myAnswer,g?.myBluff,g?.myVote,g?.sequencePhase,g?.sequenceRound,room.players.find(p=>p.id===room.me)?.carry,g?.correctGuessers?.includes(room.me)].join('|');
if(renderKey===key){live();return;}key=renderKey;cancelAnimationFrame(animation);direction={x:0,y:0};mapPosition=null;lastGestureTask=-1;
if(!room){app.innerHTML=session?`${header()}<main class="wrap"><div class="waiting"><h2>CONNECTING TO<br>YOUR PARTY…</h2><button class="btn" data-leave>BACK TO ARCADE</button></div></main>`:window.joinMode||requested?joinPage():home();}
else if(!g)app.innerHTML=lobby();else if(g.phase==='results')app.innerHTML=results();else app.innerHTML=({quiz,bluff,sketch,restore,kruger}[g.type])();
bind();live();window.scrollTo(0,0);if($('#qr')&&typeof window.qrcode==='function'){const qr=window.qrcode(0,'M');qr.addData(joinURL(room.code));qr.make();$('#qr').innerHTML=qr.createSvgTag({cellSize:3,margin:1,scalable:true});}for(const c of $$('.map-preview'))drawMap(c,null,true);
if($('#draw'))setupDrawing();if($('#drawing-view'))paintDrawing($('#drawing-view'),room.game.drawing||[]);if($('#kruger-canvas')){mapPosition=me()?{x:me().x,y:me().y}:null;bindKruger();animateWorld();}if(g?.type==='restore'&&g.phase==='restore'){restoreQueue=[];bindRestoration();animateRestoration();}}
function live(){if(!room)return;$$('[data-score]').forEach(el=>{el.textContent=room.players.find(p=>p.id===el.dataset.score)?.score||0});const g=room.game;if(!g)return;$$('[data-timer]').forEach(el=>{const seconds=Math.max(0,Math.ceil(((g.deadline||now())-now())/1000));el.textContent=g.deadline?String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'):'';});const count=g.type==='quiz'?g.answered?.length:g.type==='bluff'?(g.phase==='write'?g.submitted?.length:g.voted?.length):g.submitted?.length;$$('[data-submitted]').forEach(el=>el.textContent=count??0);if($('#connection'))$('#connection').textContent=failures?'RECONNECTING…':'CONNECTED';
if(g.type==='restore')restoreLive();
if(g.type==='kruger'){updateKrugerUI();const p=me();if(p&&mapPosition&&distance(p,mapPosition)>120)mapPosition={x:p.x,y:p.y};}
}
