$$('[data-preview-menu]').forEach(b=>b.onclick=e=>{e.preventDefault();if(previewMode)stopPreview();else{session=null;room=null;window.joinMode=false;history.replaceState({},'','?preview=all');key='';render();document.querySelector('#games')?.scrollIntoView({behavior:'smooth'});}});
