function previewHeader(){const g=room.game;const labels={quiz:room.game.phase==='answer'?'Reveal answer':'Next question',bluff:room.game.phase==='write'?'Start voting':room.game.phase==='vote'?'Reveal truth':'Next character',kruger:room.game.phase==='chapter'?'End chapter':'Next chapter',restore:'Finish preview',sketch:room.game.phase==='draw'?'Show drawings':room.game.phase==='guess'?'Reveal drawing':'Next drawing'};return `${header()}<section class="preview-toolbar"><div><span class="preview-status">LOCAL PLAYABLE PREVIEW</span><p>Just you + two simulated teammates. No room needed.</p></div><select id="preview-game" aria-label="Choose a game preview">${Object.entries(GAMES).map(([id,item])=>`<option value="${id}" ${g?.type===id?'selected':''}>${esc(item.title)}</option>`).join('')}</select>${g.type==='kruger'?`<select id="preview-chapter" aria-label="Preview chapter">${CHAPTERS.map((c,i)=>`<option value="${i}" ${g.chapter===i?'selected':''}>${esc(c.title)}</option>`).join('')}</select>`:''}<div class="actions"><button class="btn small" data-preview-screen>${room.host?'PLAY ON PHONE':'SEE TV SCREEN'}</button>${g.phase!=='results'?`<button class="btn small" data-advance>${labels[g.type]||'Next phase'} →</button>`:''}<button class="btn small" data-preview="${g.type}">RESTART</button><button class="btn small" data-feedback>GIVE FEEDBACK</button><button class="btn small" data-preview-menu>ALL FIVE GAMES</button></div></section>`;}
async function startPreview(type){if(!GAMES[type]||busy)return;busy=true;try{previewEngine??=await import('./server/engine.mjs');previewMode=true;previewScreen='player';session=null;previewBotAt=0;previewStarted=Date.now();previewState=previewEngine.createRoom('DEMO','preview-host',Date.now(),true);if(type==='sketch')previewState.pack.sketch=['A sofa','An office','A tree'];['You','Moss Bot','Reef Bot'].forEach((name,i)=>previewEngine.joinRoom(previewState,name,'preview-'+i,Date.now()));previewEngine.hostAction(previewState,{type:'start',game:type,duration:180},Date.now());if(type==='restore')previewState.game.sequence=[0,1,2];history.replaceState({},'','?preview='+type);key='';room=null;accept(previewView());}catch(e){toast(e.message);}finally{busy=false;}}
function previewView(){previewState.revision++;return previewEngine.view(previewState,previewScreen==='host'?'preview-host':'preview-0',Date.now());}
function stopPreview(){previewMode=false;previewState=null;previewScreen='player';room=null;session=null;clockOffset=0;window.joinMode=false;history.replaceState({},'','?preview=all');key='';render();$('#games')?.scrollIntoView({behavior:'smooth'});}
function previewRequest(op,data={}){const t=Date.now();previewEngine.tick(previewState,t);for(const p of previewState.players)p.seen=t;if(op==='host')previewEngine.hostAction(previewState,data.action,t);if(op==='player')previewEngine.playerAction(previewState,previewState.players[0],data.action,t);
 const g=previewState.game;if(g&&g.phase!=='results'&&t-previewBotAt>1100){previewBotAt=t;for(let i=1;i<3;i++){const p=previewState.players[i];try{
 if(g.type==='quiz'&&g.phase==='answer'&&!(p.id in g.answers))previewEngine.playerAction(previewState,p,{type:'answer',answer:(previewState.pack.quiz[g.index].correct+i-1)%4},t);
 if(g.type==='bluff'&&g.phase==='write'&&!(p.id in g.bluffs))previewEngine.playerAction(previewState,p,{type:'bluff',text:['A suitcase containing only office snacks','A handwritten business plan for a pigeon café'][i-1]},t);
 if(g.type==='bluff'&&g.phase==='vote'&&!(p.id in g.votes)){const options=g.options.filter(o=>o.owner!==p.id);previewEngine.playerAction(previewState,p,{type:'vote',option:options[(i-1)%options.length].id},t);}
 if(g.type==='sketch'&&g.phase==='draw'&&!(p.id in g.drawings))previewEngine.playerAction(previewState,p,{type:'drawing',strokes:i===1?[[[.25,.8],[.25,.3],[.75,.3],[.75,.8],[.25,.8]],[[.2,.3],[.5,.08],[.8,.3]],[[.45,.8],[.45,.55],[.58,.55],[.58,.8]]]:[[[.5,.85],[.5,.38]],[[.25,.5],[.5,.14],[.75,.5],[.25,.5]],[[.2,.66],[.5,.35],[.8,.66],[.2,.66]]]},t);
 if(g.type==='sketch'&&g.phase==='guess'&&t-g.started>8000&&g.artist!==i&&!g.correctGuessers.includes(p.id))previewEngine.playerAction(previewState,p,{type:'guess',text:g.prompts[previewState.players[g.artist].id]},t);
 if(g.type==='kruger'&&g.phase==='chapter'&&g.scene){const c=g.scene,you=previewState.players[0];if(['talk','outcome','done'].includes(c.stage)&&c.ready[you.id])previewEngine.playerAction(previewState,p,{type:'dialogue-ready',scene:c.id,stage:c.stage,page:c.page},t);if(c.stage==='vote'&&c.votes[you.id]!==undefined)previewEngine.playerAction(previewState,p,{type:'dialogue-vote',scene:c.id,choice:i===1?c.votes[you.id]:(c.votes[you.id]+1)%3},t);if(c.stage==='challenge'&&(c.taps[you.id]||0)>0)previewEngine.playerAction(previewState,p,{type:'dialogue-tap',scene:c.id,count:4},t);}

 if(g.type==='restore'&&g.phase==='restore'&&g.sequencePhase==='repeat'&&!p.sequenceDone){const button=g.sequence[p.sequenceCursor];if(button!==undefined)previewEngine.playerAction(previewState,p,{type:'restore-sequence',buttons:[button],cursor:p.sequenceCursor,round:g.sequenceRound},t);}
 }catch{}}}return previewView();}
function feedbackDialog(){const type=room?.game?.type||'arcade';let notes={};try{notes=JSON.parse(localStorage.getItem('sumthing-feedback')||'{}');}catch{}const el=document.createElement('div');el.className='help-dialog';el.innerHTML=`<div><p class="eyebrow">YOUR FEEDBACK · ${esc(GAMES[type]?.title||'The arcade')}</p><h2>WHAT SHOULD CHANGE?</h2><p>Notes stay on this device. Save them as you test, then copy everything and paste it into our chat.</p><label for="feedback-note">WHAT WORKS, WHAT DOESN’T, AND YOUR IDEAS</label><textarea id="feedback-note" rows="6" placeholder="For example: the map needs a closer camera…">${esc(notes[type]||'')}</textarea><div class="actions" style="margin-top:15px"><button class="btn lime" data-save-feedback>SAVE NOTE</button><button class="btn" data-copy-notes>COPY ALL FEEDBACK</button><button class="btn" data-close-feedback>CLOSE</button></div></div>`;document.body.append(el);el.querySelector('[data-save-feedback]').onclick=()=>{notes[type]=el.querySelector('textarea').value;localStorage.setItem('sumthing-feedback',JSON.stringify(notes));toast('Feedback saved on this device.');el.remove();};el.querySelector('[data-copy-notes]').onclick=()=>{notes[type]=el.querySelector('textarea').value;localStorage.setItem('sumthing-feedback',JSON.stringify(notes));copyFeedback();};el.querySelector('[data-close-feedback]').onclick=()=>el.remove();}
async function copyFeedback(){let notes={};try{notes=JSON.parse(localStorage.getItem('sumthing-feedback')||'{}');}catch{}const text=Object.entries(notes).filter(([,v])=>v.trim()).map(([k,v])=>(GAMES[k]?.title||k)+'\n'+v).join('\n\n');if(!text){toast('Save a feedback note first.');return;}try{await navigator.clipboard.writeText(text);toast('All feedback copied. Paste it into our chat.');}catch{download('sumthing-feedback.txt',text);}}
function restorationToolText(){return '';}
function bindRestoration(){const g=room.game;if(g.sequence?.length)sequencePattern=[...g.sequence];sequenceLocalCursor=me()?.sequenceCursor||0;sequenceQueue=[];sequenceSending=false;$$('[data-sequence-button]').forEach(b=>b.onclick=()=>{if(room.host||room.game.sequencePhase!=='repeat'||me().sequenceDone)return;const button=Number(b.dataset.sequenceButton);b.classList.add('pressed');setTimeout(()=>b.classList.remove('pressed'),130);if(sequenceQueue.length<12)sequenceQueue.push(button);flushSequence();});}
async function flushSequence(){if(sequenceSending||!sequenceQueue.length||room?.game?.sequencePhase!=='repeat')return;const buttons=sequenceQueue.splice(0,12),cursor=sequenceLocalCursor,round=room.game.sequenceRound;sequenceSending=true;try{const result=await request('player',{action:{type:'restore-sequence',buttons,cursor,round}});const player=result.players.find(p=>p.id===result.me);sequenceLocalCursor=player?.sequenceCursor||0;if(player?.sequenceLastWrong>sequenceLastWrong){sequenceLastWrong=player.sequenceLastWrong;sequenceQueue=[];}accept(result);}catch(e){sequenceQueue=[];toast(e.message);}finally{sequenceSending=false;if(sequenceQueue.length)flushSequence();}}
function restoreLive(){const g=room?.game;if(!g||g.type!=='restore')return;const p=me();const t=now();if(g.sequence?.length)sequencePattern=[...g.sequence];$$('[data-progress]').forEach(el=>el.textContent=g.progress);const n=Math.floor((t-g.sequenceAt-1000)/700);const flash=g.sequencePhase==='watch'&&n>=0&&n<sequencePattern.length&&((t-g.sequenceAt-1000)%700)<520?sequencePattern[n]:-1;$$('[data-sequence-cue]').forEach(el=>el.classList.toggle('lit',Number(el.dataset.sequenceCue)===flash));if($('#sequence-message'))$('#sequence-message').textContent=g.sequencePhase==='watch'?(n<0?'READY? WATCH THE ORDER':'WATCH '+(Math.min(n+1,sequencePattern.length))+' / '+sequencePattern.length):g.sequencePhase==='repeat'?'GO! REPEAT THE ORDER':'NICE WORK. NEXT PATTERN…';if($('#sequence-remaining'))$('#sequence-remaining').textContent=g.sequencePhase==='repeat'?Math.max(0,Math.ceil((g.inputDeadline-t)/1000))+'s':'';if(p){$$('[data-sequence-button]').forEach(b=>b.disabled=g.sequencePhase!=='repeat'||p.sequenceDone);if($('#sequence-dots'))$('#sequence-dots').innerHTML=Array.from({length:g.sequenceLength},(_,i)=>`<i class="${i<p.sequenceCursor?'done':''}"></i>`).join('');if($('#sequence-personal'))$('#sequence-personal').textContent=p.sequenceSuccess?'HABITAT RESTORED! +'+p.lastSequencePoints+' POINTS':p.sequenceDone?'NEXT PATTERN IS A FRESH START':p.sequenceLastWrong&&t-p.sequenceLastWrong<2200?'WRONG ORDER. START AGAIN.':g.sequencePhase==='repeat'?'TAP THE BUTTONS IN THE ORDER YOU SAW':'WATCH THE TV. YOUR BUTTONS WILL UNLOCK.';if($('#sequence-tries'))$('#sequence-tries').textContent='TRIES '+Math.max(0,3-p.sequenceMistakes)+' / 3 · STREAK '+p.sequenceStreak;}$$('[data-sequence-player]').forEach(el=>{const player=room.players.find(p=>p.id===el.dataset.sequencePlayer);if(!player)return;el.classList.toggle('restored',player.sequenceSuccess);el.querySelector('.habitat-player-status').textContent=player.sequenceSuccess?'RESTORED!':player.sequenceDone?'NEXT ROUND':g.sequencePhase==='repeat'?player.sequenceCursor+' / '+g.sequenceLength:'WATCHING';el.querySelector('.habitat-player-count').textContent=player.restored+' habitats';});const garden=$('#habitat-trees');if(garden){const count=g.restoredPatches?.length||0;if(Number(garden.dataset.count)!==count){garden.dataset.count=count;garden.innerHTML=Array.from({length:Math.min(35,count)},(_,i)=>`<span style="left:${4+(i*19)%91}%;bottom:${9+(i*7)%22}px;animation-delay:${i*.03}s">♠</span>`).join('');}}}
function animateRestoration(){const loop=()=>{if(!$('#habitat-game')||room?.game?.type!=='restore'||room.game.phase!=='restore')return;restoreLive();animation=requestAnimationFrame(loop);};animation=requestAnimationFrame(loop);}
function animalAvatar(i,color){if(i%3===0)return `<svg viewBox="0 0 80 80" aria-hidden="true"><path d="M12 13L31 23H49L68 13L62 55L40 71L18 55Z" fill="${color}"/><path d="M18 43L40 58L62 43L57 63L40 73L23 63Z" fill="#fff9e8"/><path d="M15 19L26 27L19 36ZM65 19L54 27L61 36Z" fill="#033532"/><circle cx="28" cy="40" r="4" fill="#033532"/><circle cx="52" cy="40" r="4" fill="#033532"/><path d="M35 55H45L40 62Z" fill="#033532"/></svg>`;if(i%3===1)return `<svg viewBox="0 0 80 80" aria-hidden="true"><path d="M13 15L31 22H49L67 15L65 57L53 70H27L15 57Z" fill="${color}"/><circle cx="28" cy="39" r="13" fill="#fff9e8"/><circle cx="52" cy="39" r="13" fill="#fff9e8"/><circle cx="28" cy="39" r="5" fill="#033532"/><circle cx="52" cy="39" r="5" fill="#033532"/><path d="M35 50H45L40 59Z" fill="#d7944b"/><path d="M27 64H53" stroke="#033532" stroke-width="3"/></svg>`;return `<svg viewBox="0 0 80 80" aria-hidden="true"><ellipse cx="37" cy="45" rx="28" ry="24" fill="${color}"/><path d="M21 30L38 23L53 33L49 53L30 63L18 48Z" fill="none" stroke="#033532" stroke-width="3"/><path d="M38 23L35 43L18 48M35 43L53 33M35 43L49 53M35 43L30 63" stroke="#033532" stroke-width="2"/><circle cx="66" cy="44" r="11" fill="#90c993"/><circle cx="69" cy="40" r="2" fill="#033532"/><path d="M15 59L11 68M49 65L53 72" stroke="#90c993" stroke-width="7"/></svg>`;}
